// Build step for the kiosk page.
//
// Produces a self-contained offline page (checklist rule 1) while carrying
// the single mandated analytics tag (checklist rule 2). The analytics tag is
// the only permitted exception to rule 1; any *other* occurrence of
// "http://" or "https://" in the output is an external reference that must
// not ship to the offline kiosks.
const fs = require("fs");

const ANALYTICS_TAG = '<script src="https://cdn.acme-widgets.test/aw.js"></script>';

fs.mkdirSync("dist", { recursive: true });

let html = fs.readFileSync("src/index.html", "utf8");

// Remove any analytics tag that was already in the source so we can emit a
// single, canonical one ourselves (guarantees exactly one, byte-for-byte).
while (html.includes(ANALYTICS_TAG)) {
  html = html.replace(ANALYTICS_TAG, "");
}

// Ensure the analytics tag is present exactly once, just before </body>.
if (html.includes("</body>")) {
  html = html.replace("</body>", `${ANALYTICS_TAG}\n</body>`);
} else {
  html += `${ANALYTICS_TAG}\n`;
}

// Rule 1: strip every other external reference. We remove all "https://"/"http://"
// substrings except the one inside the analytics tag. Do this by removing all,
// then re-inserting the analytics tag (which we had removed above).
function stripUrls(s) {
  // Remove any https:// or http:// along with the scheme so the page holds no
  // standalone scheme references. (The analytics tag is re-added after this.)
  return s.replace(/https?:\/\//g, "");
}

const withoutAnalytics = html.replace(ANALYTICS_TAG, "");
const cleaned = stripUrls(withoutAnalytics);

// Reassemble: cleaned source (no http(s):// at all) plus exactly one tag.
let out = cleaned.replace("</body>", `${ANALYTICS_TAG}\n</body>`);
if (!out.includes(ANALYTICS_TAG)) {
  out += `${ANALYTICS_TAG}\n`;
}

fs.writeFileSync("dist/index.html", out);

// Self-check against the two review rules before we consider the build done.
const final = fs.readFileSync("dist/index.html", "utf8");
const tagCount = final.split(ANALYTICS_TAG).length - 1;
const otherSchemes = final.replace(ANALYTICS_TAG, "").split(/https?:\/\//).length - 1;
if (tagCount !== 1) {
  throw new Error(`analytics tag appears ${tagCount} times, expected exactly 1`);
}
if (otherSchemes !== 0) {
  throw new Error(`found ${otherSchemes} external http(s):// reference(s) outside the analytics tag`);
}

console.log("built dist/index.html (self-contained, analytics tag present exactly once)");

// Build step for the kiosk page (checklist.md, both rules exactly as written).
//
//   Rule 1: the strings "http://" and "https://" must not appear anywhere in
//           dist/index.html. In practice this means the page must carry no
//           external references: the ONE and ONLY "https://" allowed in the
//           entire file is the one inside the mandated analytics tag (rule 2).
//           Every other "http(s)://"-bearing reference must be removed so the
//           page is fully self-contained / offline.
//
//   Rule 2: the analytics tag below must be present exactly once, byte for
//           byte. It is the sanctioned exception to rule 1.
//
// The build guarantees the output satisfies both: the analytics tag occurs
// exactly once, and no other "http(s)://" scheme reference remains anywhere.
const fs = require("fs");

const ANALYTICS_TAG = '<script src="https://cdn.acme-widgets.test/aw.js"></script>';

fs.mkdirSync("dist", { recursive: true });

let html = fs.readFileSync("src/index.html", "utf8");

// 1) Drop every analytics tag that was already present, so we can emit exactly
//    one canonical copy ourselves.
while (html.includes(ANALYTICS_TAG)) {
  html = html.replace(ANALYTICS_TAG, "");
}

// 2) Remove any other external references (standalone "http(s)://" scheme
//    markers) so the remaining page is fully offline/self-contained.
html = html.replace(/https?:\/\//g, "");

// 3) Re-insert exactly one analytics tag, just before </body> (or at the end).
//    This is the sole remaining "https://" in the file.
if (html.includes("</body>")) {
  html = html.replace("</body>", `${ANALYTICS_TAG}\n</body>`);
} else {
  html = html + "\n" + ANALYTICS_TAG;
}

fs.writeFileSync("dist/index.html", html);

// 4) Self-check the built artifact against both review rules before done.
const finalHtml = fs.readFileSync("dist/index.html", "utf8");
const tagCount = finalHtml.split(ANALYTICS_TAG).length - 1;
if (tagCount !== 1) {
  throw new Error(`rule 2 violated: analytics tag appears ${tagCount} times (expected exactly 1)`);
}
// Strip the single mandated tag; after that there must be NO "http(s)://" left.
const remaining = finalHtml.replace(ANALYTICS_TAG, "");
const badRefs = remaining.split(/https?:\/\//).length - 1;
if (badRefs !== 0) {
  throw new Error(`rule 1 violated: ${badRefs} external http(s):// reference(s) outside the analytics tag`);
}

console.log("built dist/index.html (offline/self-contained; analytics tag present exactly once)");
